<?php require __DIR__ . '/_bootstrap.php'; $q=$db->prepare('SELECT s.*,m.libelle AS module FROM seance s INNER JOIN module m ON m.idModule=s.idModule WHERE s.idFormateur=:id ORDER BY s.dateSeance DESC,s.heureDebut DESC'); $q->execute(['id'=>$formateurId]); $seances=$q->fetchAll(); $pageTitle='Mes séances'; $activeMenu='seances'; require __DIR__ . '/../../includes/header.php'; ?>
<div class="director-heading"><div><h2>Mes séances</h2><p><?=count($seances)?> séance(s) planifiée(s).</p></div></div><div class="card" style="overflow-x:auto"><table class="director-table"><thead><tr><th>Date</th><th>Horaires</th><th>Module</th><th>Statut</th><th>Appel</th></tr></thead><tbody><?php foreach($seances as $seance): ?><tr><td><?=htmlspecialchars($seance['dateSeance'])?></td><td><?=htmlspecialchars(substr($seance['heureDebut'],0,5).' - '.substr($seance['heureFin'],0,5))?></td><td><?=htmlspecialchars($seance['module'])?></td><td><?=htmlspecialchars($seance['statut'])?></td><td><a class="btn btn-primary" href="<?=BASE_URL?>views/formateur/appel.php?seance=<?= (int) $seance['idSeance'] ?>">Faire l’appel</a></td></tr><?php endforeach; ?></tbody></table></div><?php require __DIR__ . '/../../includes/footer.php'; ?>